class Example {
    var name: String? = null // var + mutable = no smart cast guarantee

    fun printName() {
        if (name != null) {
            // println(name.length) // won't compile: name could change
            println(name!!.length)   // needs !! or a local val copy
        }
        val localName = name
        if (localName != null) {
            println(localName.length) // fine: local val can't change
        }
    }
}

@OptIn(ExperimentalContracts::class)
fun requireValidUser(user: User?): Boolean {
    contract {
        returns(true) implies (user != null)
    }
    return user != null && user.isActive
}

fun greet(user: User?) {
    if (requireValidUser(user)) {
        println(user.name) // smart-cast to non-null works here
    }
}
